import java.util.HashMap;
import java.util.Map;
class Rq {
    private final String actionName;
    private final Map<String, String> params = new HashMap<>();
    Rq(String request) {
        String[] parts = request.split("\\?", 2);
        actionName = parts[0];
        // 조건이 없으면 빈 Map을 유지해요.
        if (parts.length == 1 || parts[1].isEmpty()) return;
        // & 로 나눈 조각마다 = 앞을 키, 뒤를 값으로 담아요.
        for (String part : parts[1].split("&")) {
            String[] pair = part.split("=");
            params.put(pair[0], pair[1]);
        }
    }
    String getActionName() { return actionName; }
    // 키가 없을 때 쓸 기본값을 함께 받아요.
    String getParam(String name, String fallback) { return params.getOrDefault(name, fallback); }
}

public class Main {
    public static void main(String[] args) {
        // 입력을 나누는 책임과 사용하는 책임을 구분해요.
        Rq rq = new Rq("update?id=2&text=hello");
        System.out.println(rq.getParam("id", "none"));
    }
}

