import java.util.Arrays;
import java.util.Map;
import java.util.stream.Collectors;
class Rq {
    private final String actionName;
    private final Map<String, String> params;
    Rq(String request) {
        String[] parts = request.split("\\?", 2);
        actionName = parts[0];
        // 조건이 없으면 빈 Map을 유지해요.
        if (parts.length == 1 || parts[1].isEmpty()) { params = Map.of(); return; }
        // 조각마다 pair로 나눈 뒤 키와 값의 Map으로 모아요.
        params = Arrays.stream(parts[1].split("&", -1))
            .map(Rq::pair)
            .collect(Collectors.toMap(pair -> pair[0], pair -> pair[1]));
    }
    private static String[] pair(String part) {
        // 값 안의 등호와 빈 값은 보존해요. 빈 키나 등호 없는 조각은 거절해요.
        String[] pair = part.split("=", 2);
        if (pair.length != 2 || pair[0].isBlank()) throw new IllegalArgumentException("parameter");
        return pair;
    }
    String getActionName() { return actionName; }
    String getParam(String name, String fallback) { return params.getOrDefault(name, fallback); }
}

public class Main {
    public static void main(String[] args) {
        // 반복문 버전과 같은 요청이에요.
        Rq rq = new Rq("update?text=hello&id=2");
        System.out.println(rq.getParam("id", "none"));
    }
}

